// ============================================================================
// 台灣國定假日清單 (2025-2026) - 只包含平日假日
// 更新日期: 2024-12-26
// 資料來源: 行政院人事行政總處
// ============================================================================
const holidays = {
  2025: {
    '2025-01-01': '元旦',           // 週三
    '2025-01-27': '春節初一',       // 週一
    '2025-01-28': '春節初二',       // 週二
    '2025-01-29': '春節初三',       // 週三
    '2025-01-30': '春節初四',       // 週四
    '2025-01-31': '春節初五',       // 週五
    '2025-02-28': '和平紀念日',     // 週五
    '2025-04-03': '兒童節',         // 週四
    '2025-04-04': '清明節',         // 週五
    '2025-05-01': '勞動節',         // 週四
    '2025-05-02': '勞動節調整放假', // 週五
    '2025-05-30': '端午節',         // 週五
    '2025-09-29': '教師節補假',     // 週一
    '2025-10-06': '中秋節',         // 週一
    '2025-10-10': '國慶日',         // 週五
    '2025-10-24': '台灣光復節補假', // 週五
    '2025-12-25': '行憲紀念日'      // 週四
  },
  2026: {
    '2026-01-01': '元旦',              // 週四
    '2026-02-16': '春節初一',          // 週一
    '2026-02-17': '春節初二',          // 週二
    '2026-02-18': '春節初三',          // 週三
    '2026-02-19': '春節初四',          // 週四
    '2026-02-20': '春節初五',          // 週五
    '2026-02-27': '和平紀念日',        // 週五
    '2026-04-03': '兒童節調整放假',    // 週五
    '2026-04-06': '清明節調整放假',    // 週一
    '2026-05-01': '勞動節',            // 週五
    '2026-06-19': '端午節',            // 週五
    '2026-09-25': '中秋節',            // 週五
    '2026-09-28': '教師節',            // 週一
    '2026-10-09': '國慶日調整放假',    // 週五
    '2026-10-26': '台灣光復節調整放假', // 週一
    '2026-12-25': '行憲紀念日'         // 週五
  }
};

// 根據年份取得假日清單
function getHolidaysByYear(year) {
  return holidays[year] || {};
}

// ============================================================================
// 主程式開始
// ============================================================================
const params = $input.first().json;
const slackToken = params.slackToken;
const sourceChannel = params.sourceChannel;
const notifyChannel = params.notifyChannel;
const attendanceChannel = params.attendanceChannel;
const excludeNames = params.excludeNames;

// 計算目標日期
const now = new Date();
const taipeiOffset = 8 * 60;
const localOffset = now.getTimezoneOffset();
const taipeiTime = new Date(now.getTime() + (taipeiOffset + localOffset) * 60 * 1000);

// 檢查今天是否為假日
const todayYear = taipeiTime.getFullYear();
const todayMonth = String(taipeiTime.getMonth() + 1).padStart(2, '0');
const todayDay = String(taipeiTime.getDate()).padStart(2, '0');
const todayDateStr = `${todayYear}-${todayMonth}-${todayDay}`;

// 取得當年假日清單
const currentYearHolidays = getHolidaysByYear(todayYear);

if (currentYearHolidays[todayDateStr]) {
  return [{
    json: {
      slackToken,
      notifyChannel,
      isHoliday: true,
      holidayDate: todayDateStr,
      holidayName: currentYearHolidays[todayDateStr],
      message: `🏖️ 今天是國定假日：${currentYearHolidays[todayDateStr]} (${todayDateStr})\n無需檢查日報，祝您假期愉快！`
    }
  }];
}

const dayOfWeek = taipeiTime.getDay();
const targetDates = [];

if (dayOfWeek === 1) {
  for (let i = 3; i >= 0; i--) {
    const date = new Date(taipeiTime);
    date.setDate(taipeiTime.getDate() - i);
    targetDates.push(date);
  }
} else if (dayOfWeek >= 2 && dayOfWeek <= 5) {
  const date = new Date(taipeiTime);
  date.setDate(taipeiTime.getDate() - 1);
  targetDates.push(date);
} else {
  return [{ json: { error: '不應在週末執行此工作流程', slackToken, notifyChannel } }];
}

// 檢查目標日期是否全部為假日
const targetDateStrs = [];
const targetDateTitles = [];
const targetDateShortStrs = [];
const holidayDates = [];

for (const date of targetDates) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const dateStr = `${year}-${month}-${day}`;

  // 取得該年份的假日清單
  const yearHolidays = getHolidaysByYear(year);

  // 檢查這個日期是否為假日
  if (yearHolidays[dateStr]) {
    holidayDates.push({ date: dateStr, name: yearHolidays[dateStr] });
  } else {
    targetDateStrs.push(dateStr);
    targetDateTitles.push(`${year}${month}${day}`);
    targetDateShortStrs.push(`${parseInt(month)}/${parseInt(day)}`);
  }
}

// 如果所有檢查日期都是假日
if (targetDateStrs.length === 0 && holidayDates.length > 0) {
  const holidayInfo = holidayDates.map(h => `${h.name} (${h.date})`).join('、');
  return [{
    json: {
      slackToken,
      notifyChannel,
      isHoliday: true,
      holidayDate: holidayDates.map(h => h.date).join(', '),
      holidayName: holidayDates.map(h => h.name).join('、'),
      message: `🏖️ 檢查日期皆為國定假日：${holidayInfo}\n無需檢查日報，祝您假期愉快！`
    }
  }];
}

// 如果部分日期為假日，在後續報告中說明
const holidayNote = holidayDates.length > 0 
  ? `\n\nℹ️ 以下日期為國定假日，已排除：${holidayDates.map(h => `${h.name} (${h.date})`).join('、')}`
  : '';

const oldestDate = targetDates[0];
const latestDate = targetDates[targetDates.length - 1];

const oldestYear = oldestDate.getFullYear();
const oldestMonth = String(oldestDate.getMonth() + 1).padStart(2, '0');
const oldestDay = String(oldestDate.getDate()).padStart(2, '0');
const oldestDateStr = `${oldestYear}-${oldestMonth}-${oldestDay}`;

const latestYear = latestDate.getFullYear();
const latestMonth = String(latestDate.getMonth() + 1).padStart(2, '0');
const latestDay = String(latestDate.getDate()).padStart(2, '0');
const latestDateStr = `${latestYear}-${latestMonth}-${latestDay}`;

// 擴大搜尋範圍到前後各 7 天，以捕獲提前發布的請假訊息
const oldestTs = Math.floor(new Date(oldestDateStr + 'T00:00:00+08:00').getTime() / 1000) - (86400 * 7);
const latestTs = Math.floor(new Date(latestDateStr + 'T23:59:59+08:00').getTime() / 1000) + (86400 * 7);

// Slack API 呼叫函數
async function slackApi(endpoint, queryParams = {}) {
  const queryString = Object.entries(queryParams)
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
    .join('&');
  const apiUrl = `https://slack.com/api/${endpoint}${queryString ? '?' + queryString : ''}`;

  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: apiUrl,
    headers: { 'Authorization': `Bearer ${slackToken}` },
    json: true
  });
  return response;
}

const callSlackApi = slackApi.bind(this);

// 日期範圍展開函數
function expandDateRange(text, currentYear) {
  const expandedDates = [];

  const rangeMatch2 = text.match(/(\d{1,2})\/(\d{1,2})\s*-\s*(\d{1,2})\/(\d{1,2})/);
  if (rangeMatch2) {
    const startMonth = parseInt(rangeMatch2[1]);
    const startDay = parseInt(rangeMatch2[2]);
    const endMonth = parseInt(rangeMatch2[3]);
    const endDay = parseInt(rangeMatch2[4]);

    const startDate = new Date(currentYear, startMonth - 1, startDay);
    const endDate = new Date(currentYear, endMonth - 1, endDay);

    const currentDate = new Date(startDate);
    while (currentDate <= endDate) {
      const year = currentDate.getFullYear();
      const month = String(currentDate.getMonth() + 1).padStart(2, '0');
      const day = String(currentDate.getDate()).padStart(2, '0');
      expandedDates.push(`${year}-${month}-${day}`);
      currentDate.setDate(currentDate.getDate() + 1);
    }
    return expandedDates;
  }

  const rangeMatch1 = text.match(/(\d{1,2})\/(\d{1,2})\s*-\s*(\d{1,2})(?!\d*\/)/);
  if (rangeMatch1) {
    const month = parseInt(rangeMatch1[1]);
    const startDay = parseInt(rangeMatch1[2]);
    const endDay = parseInt(rangeMatch1[3]);

    for (let day = startDay; day <= endDay; day++) {
      const monthStr = String(month).padStart(2, '0');
      const dayStr = String(day).padStart(2, '0');
      expandedDates.push(`${currentYear}-${monthStr}-${dayStr}`);
    }
    return expandedDates;
  }

  return expandedDates;
}

// 整天請假判斷函數
function isFullDayLeave(text) {
  const lowerText = text.toLowerCase();

  if (/\d{1,2}:\d{2}/.test(text) || /\d{1,2}\s*[-~]\s*\d{1,2}(?!\/)/.test(text)) {
    const hasDateRange = /\d{1,2}\/\d{1,2}\s*-/.test(text);
    if (!hasDateRange) {
      return false;
    }
  }

  const hasMention = /@[\w-]+/.test(text) || /<@[A-Z0-9]+>/.test(text);

  const hasChineseTimeKeyword = lowerText.includes('上午') ||
    lowerText.includes('下午') ||
    lowerText.includes('早上') ||
    lowerText.includes('中午') ||
    lowerText.includes('晚上');

  if (hasChineseTimeKeyword) {
    return false;
  }

  if (!hasMention) {
    const hasEnglishTimeKeyword = /\bam\b/.test(lowerText) || /\bpm\b/.test(lowerText);
    if (hasEnglishTimeKeyword) {
      return false;
    }
  }

  const leaveKeywords = ['請假', '病假', '事假', '年假', '特休', '休假', '生日假', '健檢'];
  return leaveKeywords.some(keyword => text.includes(keyword));
}

function findUserIdByName(name, userMap) {
  const cleanName = name.replace('@', '');
  for (const [userId, userInfo] of Object.entries(userMap)) {
    if (userInfo.name === cleanName) {
      return userId;
    }
  }
  return null;
}

function extractUserIdentifier(text, userMap) {
  const userIdMatch = text.match(/<@([A-Z0-9]+)>/);
  if (userIdMatch) {
    return userIdMatch[1];
  }

  const nameMatch = text.match(/@([\w\u4e00-\u9fa5]+-[\w\u4e00-\u9fa5]+)/);
  if (nameMatch) {
    const name = nameMatch[1];
    const userId = findUserIdByName(name, userMap);
    if (userId) {
      return userId;
    }
  }

  return null;
}

// 1. 取得頻道成員
let channelMemberIds = [];
let membersCursor = '';

do {
  const membersParams = { channel: sourceChannel, limit: '200' };
  if (membersCursor) membersParams.cursor = membersCursor;

  const membersResult = await callSlackApi('conversations.members', membersParams);

  if (!membersResult.ok) {
    return [{ json: { error: '無法取得頻道成員', detail: membersResult.error, slackToken, notifyChannel } }];
  }

  channelMemberIds = channelMemberIds.concat(membersResult.members || []);
  membersCursor = membersResult.response_metadata?.next_cursor || '';
} while (membersCursor);

// 2. 只取得彙報 channel 成員的用戶資訊
const userMap = {};
const botIds = new Set();

for (const memberId of channelMemberIds) {
  const userResult = await callSlackApi('users.info', { user: memberId });

  if (userResult.ok) {
    const user = userResult.user;
    const displayName = user.profile?.display_name || user.real_name || user.name || 'Unknown';
    userMap[user.id] = {
      name: displayName,
      isBot: user.is_bot || false,
      deleted: user.deleted || false
    };
    if (user.is_bot) {
      botIds.add(user.id);
    }
  }
}

// 3. 過濾出真正需要追蹤的成員
const trackableMembers = [];

for (const memberId of channelMemberIds) {
  const userInfo = userMap[memberId];

  if (!userInfo) continue;
  if (userInfo.isBot) continue;
  if (userInfo.deleted) continue;
  if (excludeNames.includes(userInfo.name)) continue;

  trackableMembers.push({ id: memberId, name: userInfo.name });
}

// 4. 取得彙報頻道的訊息
let allMessages = [];
let historyCursor = '';

do {
  const historyParams = {
    channel: sourceChannel,
    oldest: oldestTs.toString(),
    latest: latestTs.toString(),
    limit: '200'
  };
  if (historyCursor) historyParams.cursor = historyCursor;

  const historyResult = await callSlackApi('conversations.history', historyParams);

  if (!historyResult.ok) {
    return [{ json: { error: '無法取得頻道歷史', detail: historyResult.error, slackToken, notifyChannel } }];
  }

  allMessages = allMessages.concat(historyResult.messages || []);
  historyCursor = historyResult.response_metadata?.next_cursor || '';
} while (historyCursor);

// 5. 統計已提交的人員
const submittedMap = new Map();

for (const msg of allMessages) {
  if (!msg.user || !msg.text) continue;

  const text = msg.text;

  for (let i = 0; i < targetDateTitles.length; i++) {
    const dateTitle = targetDateTitles[i];
    const dateStr = targetDateStrs[i];

    if (text.includes(dateTitle)) {
      const msgTs = parseFloat(msg.ts);
      const submitTime = new Date(msgTs * 1000);
      const taipeiSubmitTime = new Date(submitTime.getTime() + (taipeiOffset + submitTime.getTimezoneOffset()) * 60 * 1000);

      const sYear = taipeiSubmitTime.getFullYear();
      const sMonth = String(taipeiSubmitTime.getMonth() + 1).padStart(2, '0');
      const sDay = String(taipeiSubmitTime.getDate()).padStart(2, '0');
      const sHours = String(taipeiSubmitTime.getHours()).padStart(2, '0');
      const sMinutes = String(taipeiSubmitTime.getMinutes()).padStart(2, '0');
      const sSeconds = String(taipeiSubmitTime.getSeconds()).padStart(2, '0');
      const timeStr = `${sYear}-${sMonth}-${sDay} ${sHours}:${sMinutes}:${sSeconds}`;

      if (!submittedMap.has(msg.user)) {
        submittedMap.set(msg.user, {
          name: userMap[msg.user]?.name || 'Unknown',
          submissions: []
        });
      }

      const userSubmissions = submittedMap.get(msg.user);
      if (!userSubmissions.submissions.some(s => s.date === dateStr)) {
        userSubmissions.submissions.push({ date: dateStr, time: timeStr });
      }
    }
  }
}

// 6. 取得出勤頻道的請假訊息
let attendanceMessages = [];
let attendanceCursor = '';

do {
  const attendanceParams = {
    channel: attendanceChannel,
    oldest: oldestTs.toString(),
    latest: latestTs.toString(),
    limit: '200'
  };
  if (attendanceCursor) attendanceParams.cursor = attendanceCursor;

  const attendanceResult = await callSlackApi('conversations.history', attendanceParams);

  if (!attendanceResult.ok) {
    return [{ json: { error: '無法取得出勤頻道歷史', detail: attendanceResult.error, slackToken, notifyChannel } }];
  }

  attendanceMessages = attendanceMessages.concat(attendanceResult.messages || []);
  attendanceCursor = attendanceResult.response_metadata?.next_cursor || '';
} while (attendanceCursor);

// 7. 解析請假人員（只檢查彙報 channel 成員）
const onLeaveMap = new Map();
const leaveKeywords = ['請假', '病假', '事假', '年假', '特休', '休假', '生日假', '健檢'];
const channelMemberSet = new Set(channelMemberIds);

for (const msg of attendanceMessages) {
  if (!msg.text) continue;

  const text = msg.text;
  const hasLeaveKeyword = leaveKeywords.some(keyword => text.includes(keyword));
  if (!hasLeaveKeyword) continue;

  const isFullDay = isFullDayLeave(text);
  if (!isFullDay) continue;

  const currentYear = targetDates[0].getFullYear();
  const rangeDates = expandDateRange(text, currentYear);
  const datesToCheck = new Set(rangeDates);

  for (let i = 0; i < targetDateStrs.length; i++) {
    const dateStr = targetDateStrs[i];
    const shortDateStr = targetDateShortStrs[i];

    const isInRange = datesToCheck.has(dateStr);
    const includesShortDate = text.includes(shortDateStr);

    if (!isInRange && !includesShortDate) continue;

    const userId = extractUserIdentifier(text, userMap);

    if (userId && (isInRange || includesShortDate)) {
      if (!channelMemberSet.has(userId)) continue;

      const userName = userMap[userId]?.name || 'Unknown';

      let leaveType = '請假';
      for (const keyword of leaveKeywords) {
        if (text.includes(keyword)) {
          leaveType = keyword;
          break;
        }
      }

      if (!onLeaveMap.has(userId)) {
        onLeaveMap.set(userId, {
          name: userName,
          leaves: []
        });
      }

      const userLeaves = onLeaveMap.get(userId);
      if (!userLeaves.leaves.some(l => l.date === dateStr)) {
        userLeaves.leaves.push({ date: dateStr, type: leaveType });
      }
    }
  }
}

// 8. 計算已提交、未提交和請假的人員
const submittedList = [];
const notSubmittedList = [];
const onLeaveList = [];

for (const member of trackableMembers) {
  const isOnLeave = onLeaveMap.has(member.id);
  const hasSubmitted = submittedMap.has(member.id);

  if (isOnLeave) {
    const info = onLeaveMap.get(member.id);
    info.leaves.sort((a, b) => a.date.localeCompare(b.date));
    onLeaveList.push({ name: member.name, leaves: info.leaves });
  } else if (hasSubmitted) {
    const info = submittedMap.get(member.id);
    info.submissions.sort((a, b) => a.time.localeCompare(b.time));
    submittedList.push({ name: member.name, submissions: info.submissions });
  } else {
    notSubmittedList.push(member.name);
  }
}

submittedList.sort((a, b) => a.submissions[0].time.localeCompare(b.submissions[0].time));
onLeaveList.sort((a, b) => a.name.localeCompare(b.name));

return [{
  json: {
    slackToken,
    notifyChannel,
    checkDates: targetDateStrs,
    trackableCount: trackableMembers.length,
    submittedCount: submittedList.length,
    notSubmittedCount: notSubmittedList.length,
    onLeaveCount: onLeaveList.length,
    submittedList: submittedList,
    notSubmittedList: notSubmittedList.sort(),
    onLeaveList: onLeaveList,
    holidayNote: holidayNote,
    isHoliday: false
  }
}];

// 從前一節點取得所有資料
const data = $input.first().json;

const slackToken = data.slackToken;
const notifyChannel = data.notifyChannel;

// ============================================================================
// 處理假日情況
// ============================================================================
if (data.isHoliday) {
  const holidayMsg = data.message;

  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://slack.com/api/chat.postMessage',
    headers: {
      'Authorization': `Bearer ${slackToken}`,
      'Content-Type': 'application/json'
    },
    body: {
      channel: notifyChannel,
      text: holidayMsg
    },
    json: true
  });

  return [{ json: { sent: true, isHoliday: true } }];
}

// ============================================================================
// 處理錯誤情況
// ============================================================================
if (data.error) {
  const errorMsg = `❌ 每日彙報檢查失敗\n錯誤: ${data.error}\n詳情: ${data.detail || '無'}`;

  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://slack.com/api/chat.postMessage',
    headers: {
      'Authorization': `Bearer ${slackToken}`,
      'Content-Type': 'application/json'
    },
    body: {
      channel: notifyChannel,
      text: errorMsg
    },
    json: true
  });

  return [{ json: { sent: true, error: true } }];
}

// ============================================================================
// 組裝正常報告訊息
// ============================================================================
const checkDatesCount = data.checkDates.length;
let message = `📊 *每日彙報檢查報告*\n`;
message += `📅 檢查日期: ${data.checkDates.join(', ')}\n\n`;
message += `👥 需追蹤人數: ${data.trackableCount}\n`;
message += `✅ 已提交: ${data.submittedCount} 人\n`;
message += `🏖️ 請假: ${data.onLeaveCount} 人\n`;
message += `❌ 未提交: ${data.notSubmittedCount} 人\n\n`;

// 顯示已提交名單(智能格式)
if (data.submittedCount > 0) {
  message += `*已提交名單:*\n`;
  for (const item of data.submittedList) {
    if (item.submissions.length === 1) {
      // 只提交 1 次：顯示完整時間
      const fullDateTime = item.submissions[0].time;
      message += `• ${item.name} (submitted at ${fullDateTime})\n`;
    } else if (item.submissions.length > 1) {
      // 提交多次：單行顯示所有時間
      const times = item.submissions.map(s => s.time).join(', ');
      message += `• ${item.name} (submitted at ${times})\n`;
    }
  }
  message += `\n`;
}

// 顯示請假名單
if (data.onLeaveCount > 0) {
  message += `*請假名單:*\n`;
  for (const item of data.onLeaveList) {
    if (item.leaves.length === 1) {
      // 只有一天請假
      const leave = item.leaves[0];
      message += `• ${item.name} (${leave.type} on ${leave.date})\n`;
    } else {
      // 多天請假
      const leaveDetails = item.leaves.map(l => `${l.type} on ${l.date}`).join(', ');
      message += `• ${item.name} (${leaveDetails})\n`;
    }
  }
  message += `\n`;
}

// 顯示未提交名單
if (data.notSubmittedCount > 0) {
  message += `*未提交名單:*\n`;
  for (const name of data.notSubmittedList) {
    message += `• ${name}\n`;
  }
} else if (data.onLeaveCount === 0) {
  message += `🎉 太棒了！所有人都已提交每日彙報！`;
} else {
  message += `🎉 太棒了！除了請假人員，所有人都已提交每日彙報！`;
}

// 加入假日註記（如果有部分日期為假日）
if (data.holidayNote) {
  message += data.holidayNote;
}

// 發送訊息
const result = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://slack.com/api/chat.postMessage',
  headers: {
    'Authorization': `Bearer ${slackToken}`,
    'Content-Type': 'application/json'
  },
  body: {
    channel: notifyChannel,
    text: message
  },
  json: true
});

return [{ json: { sent: result.ok, messageTs: result.ts } }];
